package com.icbc.changzhou.ipam;

import com.google.gson.JsonObject;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** Regression gate for the confirmed six-network baseline, including an actual V001-to-V012 runtime upgrade. */
public final class StageFourBaselineSmokeTest {
  public static void main(String[] args)throws Exception{
    Path work=Files.createTempDirectory("ipam-stage4-"),db=work.resolve("baseline.db");
    Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Constructor<?> ctor=type.getDeclaredConstructor(Path.class);ctor.setAccessible(true);Object runtime=ctor.newInstance(db);java.lang.reflect.Method migrate=type.getDeclaredMethod("migrate");migrate.setAccessible(true);migrate.invoke(runtime);
    try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM schema_history WHERE version='018'",1);assertCount(c,"SELECT count(*) FROM pragma_table_info('ip_application') WHERE name='override_reason'",1);c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('admin','x','管理员','ADMIN',1,0,1)");c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('tech','x','科技管理员','TECH_ADMIN',1,0,0)");c.createStatement().execute("INSERT INTO branch(code,name,is_active) VALUES('B1','测试支行',1)");c.createStatement().execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O1','测试网点',1)");}
    PhaseFourService service=new PhaseFourService(db);JsonObject plan=new JsonObject();plan.addProperty("branchId",1);plan.addProperty("outletId",1);plan.addProperty("productionCidr","108.56.0.0/24");Map<String,Object> preview=service.previewPlan(plan);if(((List<?>)preview.get("segments")).size()!=6)throw new AssertionError("six-network preview missing segments");service.createPlan(plan,1L);
    try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM ip_range WHERE outlet_id=1 AND range_type IS NOT NULL",6);assertCount(c,"SELECT count(*) FROM ip_address_pool",1524);assertCount(c,"SELECT count(*) FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id WHERE p.ip_address=r.gateway",6);assertCount(c,"SELECT count(*) FROM schema_history WHERE version='011'",1);c.createStatement().execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O2','批量测试网点',1)");}Map<String,Object> imported=service.previewPlanImport("plans.csv",("branch_code,outlet_code,production_cidr\nB1,O2,108.56.16.0/24\n").getBytes(java.nio.charset.StandardCharsets.UTF_8),1L);if(!"PREVIEW_READY".equals(imported.get("status"))||((List<?>)imported.get("previews")).size()!=1)throw new AssertionError("plan import preview missing");service.confirmPlanImport(((Number)imported.get("id")).longValue(),1L);try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM ip_range WHERE outlet_id=2 AND range_type IS NOT NULL",6);}if(new PhaseTwoService(db).ranges().stream().filter(x->x.get("rangeType")!=null).count()!=12)throw new AssertionError("six-network list must expose batch-created rangeType");
    if(!service.assets(null,true).isEmpty())throw new AssertionError("V017 must start with an empty asset list");JsonObject asset=new JsonObject();asset.addProperty("assetType","NON_TECH");asset.addProperty("name","基线资产");asset.addProperty("requiresUser",0);asset.addProperty("requiresResourceCode",0);asset.addProperty("recommendedRangeType","OFFICE");asset.addProperty("active",1);long assetId=((Number)service.createAsset(asset,1L).get("id")).longValue();JsonObject app=new JsonObject();app.addProperty("branchId",1);app.addProperty("outletId",1);app.addProperty("assetId",assetId);long appId=service.submitApplication(2L,app);Map<String,Object> candidates=service.candidates(appId,null,"",1);if(!"OFFICE".equals(candidates.get("rangeType"))||((List<?>)candidates.get("items")).isEmpty())throw new AssertionError("asset recommended segment candidates missing");long pool=((Number)((Map<?,?>)((List<?>)candidates.get("items")).get(0)).get("id")).longValue();service.approve(appId,pool,"OFFICE","测试审批",1L);Map<String,Object> approved=service.applications("APPROVED","").get(0);if(!"OFFICE".equals(approved.get("finalRangeType"))||approved.get("finalIpAddress")==null||!"基线资产".equals(approved.get("assetName")))throw new AssertionError("asset approval must retain final network, IP and asset snapshot");Map<String,Object> page=service.pool(null,null,"MONITORING","",1);if(((Number)page.get("total")).longValue()<254)throw new AssertionError("new pool query missing type filter");dynamicPrefix(service,db);System.out.println("PASS|STAGE4_V017_ASSET_RULE_POOL_QUERY|"+work);
  }
  private static void dynamicPrefix(PhaseFourService service,Path db)throws Exception{try(Connection c=open(db)){c.createStatement().execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O27','/27测试网点',1)");}JsonObject plan=new JsonObject();plan.addProperty("branchId",1);plan.addProperty("outletId",3);plan.addProperty("productionCidr","108.56.32.0/27");Map<String,Object> preview=service.previewPlan(plan);List<?> segments=(List<?>)preview.get("segments");if(segments.size()!=6||!"108.56.32.0/27".equals(((Map<?,?>)segments.get(0)).get("cidr")))throw new AssertionError("per-outlet /27 prefix not preserved");service.createPlan(plan,1L);try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM ip_range WHERE outlet_id=3 AND cidr LIKE '%/27'",6);assertCount(c,"SELECT count(*) FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id WHERE r.outlet_id=3",180);}}
  private static Connection open(Path db)throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");}return c;}
  private static void assertCount(Connection c,String sql,long expected)throws Exception{try(ResultSet r=c.createStatement().executeQuery(sql)){r.next();if(r.getLong(1)!=expected)throw new AssertionError(sql+" expected="+expected+" actual="+r.getLong(1));}}
}
